   for(int i=0;i<data.heroes.Length;i++){var h=Child(root,data.heroes[i].name).AddComponent<MainHero>();h.enabled=false;h.heroController=world.heroController;h.HeroNum=i;h.Level=1;h.iconSet=data.heroes[i].iconGuids.Select(g=>AssetDatabase.LoadAssetAtPath<Sprite>(AssetDatabase.GUIDToAssetPath(g))).ToArray();world.heroController.mainHeroes[i]=h;}
