   r.observations.Add("SOURCE_SPRITE_COUNTS original="+source.Length+" actual="+actual.Length+" parser=existing Newtonsoft.Json MaxDepth128; original tree data unchanged");
   foreach(string guid in source.Select(n=>n.renderer.spriteGuid).Distinct())
