    bool valid=sprite!=null&&sprite.texture!=null&&sprite.bounds.size.x>0&&sprite.bounds.size.y>0&&sprite.vertices.Length>=3;
    if(!valid)r.observations.Add("FAILED_SPRITE guid="+guid+" path="+path+" clrNull="+ReferenceEquals(sprite,null)+" alive="+(sprite!=null)+" type="+(ReferenceEquals(sprite,null)?"CLR null":sprite.GetType().FullName)+" mainType="+(ReferenceEquals(main,null)?"CLR null":main.GetType().FullName)+" name="+(sprite!=null?sprite.name:"Unity null")+" texture="+(sprite!=null&&sprite.texture!=null?sprite.texture.name:"null")+" vertices="+(sprite!=null?sprite.vertices.Length:-1)+" bounds="+(sprite!=null?sprite.bounds.ToString():"null"));
   }
