    resetCamera(12.100006f);w.activeBolumler[0].transform.position=new Vector3(3,4,2.3999939f);w.activeBolumler[1].transform.position=new Vector3(3,4,104.4f);w.activeBolumler[2].transform.position=new Vector3(3,4,206.399994f);
    Call(w,"UpdateBolumPositions");Check(r,settled()&&Math.Abs(w.activeBolumler[2].transform.position.z-308.399994f)<.0001f,"Desktop adapter actual73 regression converges old206.4 last chunk to308.4 in same camera frame");
    var stableRefs=w.activeBolumler.ToArray();var stablePositions=w.activeBolumler.Select(g=>g.transform.position).ToArray();var stableActive=w.activeBolumler.Select(g=>g.activeSelf).ToArray();
    for(int i=0;i<10;i++)Call(w,"UpdateBolumPositions");
    Check(r,w.activeBolumler.SequenceEqual(stableRefs)&&Enumerable.Range(0,3).All(i=>w.activeBolumler[i].transform.position.Equals(stablePositions[i])&&w.activeBolumler[i].activeSelf==stableActive[i]),"Converged adapter exact state remains stable with stationary camera");
    Call(w,"InitManualLevelRewards");w.portal=HomeWorldFixtureSupport.Child(root.transform,"OriginalPortalTest").transform;w.cameraHandler.minZ=-230f;
    foreach(int level in Enumerable.Range(0,18).Concat(new[]{20,24,100}))
    {
     GameManager.Level=level;w.UpdateMaxZForCurrentLevel();float nativeMax=w.cameraHandler.maxZ,min=w.cameraHandler.minZ;
     resetCamera(min);Call(w,"UpdateBolumPositions");w.cameraTransform.position=new Vector3(0,0,nativeMax);Call(w,"UpdateBolumPositions");
     Check(r,settled()&&w.cameraHandler.maxZ==nativeMax&&w.cameraHandler.minZ==min&&w.activeBolumler.Select(g=>g.GetInstanceID()).OrderBy(x=>x).SequenceEqual(originalObjects.Select(g=>g.GetInstanceID()).OrderBy(x=>x)),"Desktop adapter single-frame original chapter range jump settles same3 tiles, preserves range level"+level);
     w.cameraTransform.position=new Vector3(0,0,min);Call(w,"UpdateBolumPositions");Check(r,settled(),"Desktop adapter immediate reverse jump settles at original min level"+level);
    }
    resetCamera(-230f);Set(w,"oldpozcamera",-230f);Set(w,"timercamera",1f);w.cameraTransform.position=new Vector3(0,0,493.7f);Call(w,"Update");Check(r,settled()&&Get<float>(w,"oldpozcamera")==493.7f,"Original Update records final camera only after desktop wrapper fully converges");
    r.observations.Add("Additional convergence tests cover an explicitly marked offline desktop adaptation. Original27 native single-step checks call UpdateBolumPositionsOnce directly.");
    r.observations.Add("Original home material references are built-in Sprites-Default; all43 non-built-in sprite GUIDs resolve statically. Real asset import checked above.");
    r.limitations.Add("Isolated actual transforms/sprite assets copied from independently parsed original scene. No player save writes; world progression is test input. Camera projection and min/max never changed by patch.");
    r.limitations.Add("No claim of rendered screen pixels or real mouse drag. Sync fixture creates world only once to avoid native Object.Destroy in non-playing Editor; chapter replacement destruction needs PlayMode visual test.");
   }
   catch(Exception ex){r.failures.Add(ex.ToString());}
   finally{UnityEngine.Object.DestroyImmediate(root);foreach(var f in saved)f.Key.SetValue(null,f.Value);OfflineKeyStore.SetVerificationRoot(oldRoot);}
   r.passed=r.failures.Count==0;File.WriteAllText(Path.Combine(r.testRoot,"home-world-results.json"),JsonUtility.ToJson(r,true));Debug.Log("HomeWorld checks="+r.checks+" passed="+r.passed+" result="+r.testRoot);return r;
  }
  public static void RunBatch(){var r=RunChecks();Debug.Log(JsonUtility.ToJson(r,true));if(!r.passed)Debug.LogError("HomeWorld failed: "+string.Join("; ",r.failures));}
 }
